// 前序
void preorder(TreeNode *r) {
    if (!r) return;
    visit(r);
    preorder(r->left);
    preorder(r->right);
}

// 中序（BST 上得到递增序列）
void inorder(TreeNode *r) {
    if (!r) return;
    inorder(r->left);
    visit(r);
    inorder(r->right);
}

// 后序
void postorder(TreeNode *r) {
    if (!r) return;
    postorder(r->left);
    postorder(r->right);
    visit(r);
}

std::vector<int> res;
std::stack<TreeNode*> st;
TreeNode *cur = root;
while (cur || !st.empty()) {
    while (cur) {            // 一路向左
        st.push(cur);
        cur = cur->left;
    }
    cur = st.top(); st.pop();
    res.push_back(cur->val); // 访问
    cur = cur->right;        // 转向右子树
}

std::vector<std::vector<int>> res;
if (!root) return res;
std::queue<TreeNode*> q;
q.push(root);
while (!q.empty()) {
    int sz = q.size();           // 本层节点数，必须先固定
    std::vector<int> level;
    for (int i = 0; i < sz; ++i) {
        TreeNode *n = q.front(); q.pop();
        level.push_back(n->val);
        if (n->left)  q.push(n->left);
        if (n->right) q.push(n->right);
    }
    res.push_back(level);
}

bool check(TreeNode *r, long long lo, long long hi) {
    if (!r) return true;
    if (r->val <= lo || r->val >= hi) return false;
    return check(r->left,  lo, r->val) &&
           check(r->right, r->val, hi);
}
bool isValidBST(TreeNode *root) {
    return check(root, LLONG_MIN, LLONG_MAX);
}

TreeNode* lca(TreeNode *r, TreeNode *p, TreeNode *q) {
    if (!r || r == p || r == q) return r;
    TreeNode *L = lca(r->left,  p, q);
    TreeNode *R = lca(r->right, p, q);
    if (L && R) return r;      // 分居两侧，当前即 LCA
    return L ? L : R;          // 都在同一侧
}

TreeNode* lcaBST(TreeNode *root, TreeNode *p, TreeNode *q) {
    TreeNode *cur = root;
    while (cur) {
        if (p->val < cur->val && q->val < cur->val) {
            cur = cur->left;       // 都在左子树
        } else if (p->val > cur->val && q->val > cur->val) {
            cur = cur->right;      // 都在右子树
        } else {
            return cur;            // 分居两侧（或当前就是其一）
        }
    }
    return nullptr;
}
